begin;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000008301','score-parent@example.invalid'),('00000000-0000-4000-8000-000000008302','score-other@example.invalid');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000008301','Synthetic','00000000-0000-4000-8000-000000008301'),('10000000-0000-4000-8000-000000008302','Other','00000000-0000-4000-8000-000000008302');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000008301','00000000-0000-4000-8000-000000008301'),('10000000-0000-4000-8000-000000008302','00000000-0000-4000-8000-000000008302');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000008301','10000000-0000-4000-8000-000000008301','Synthetic',5),('20000000-0000-4000-8000-000000008302','10000000-0000-4000-8000-000000008302','Other',5);
insert into gina.child_education_periods(id,child_id,family_id,academic_year,grade,school,starts_on,reason) values('30000000-0000-4000-8000-000000008301','20000000-0000-4000-8000-000000008301','10000000-0000-4000-8000-000000008301',2026,5,'School',current_date-30,'initial');
insert into public.child_shares(family_id,child_id,label,scopes,token_hash) values('10000000-0000-4000-8000-000000008301','20000000-0000-4000-8000-000000008301','Synthetic share',array['grades'],extensions.digest(repeat('a',43),'sha256'));
create function pg_temp.child() returns uuid language sql as $$select '20000000-0000-4000-8000-000000008301'::uuid$$;
create function pg_temp.grade() returns uuid language sql as $$select '40000000-0000-4000-8000-000000008301'::uuid$$;
create function pg_temp.value(score int default 80,day date default current_date) returns jsonb language sql as $$select jsonb_build_object('subject','Matematik','kind','exam','score',score,'max_score',100,'graded_on',day,'note','Private parent note')$$;
create function pg_temp.rows(removed boolean default false) returns jsonb language sql as $$select public.school_grade_records(pg_temp.child(),p_withdrawn=>removed)$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008301","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008301","role":"parent"}}',true);
select is((public.change_school_grade('50000000-0000-4000-8000-000000008301',pg_temp.grade(),pg_temp.child(),0,'save',pg_temp.value())->>'revision')::int,1,'create returns revision');
select is((public.change_school_grade('50000000-0000-4000-8000-000000008301',pg_temp.grade(),pg_temp.child(),0,'save',pg_temp.value())->>'revision')::int,1,'same request replay cannot create twice');
select is(jsonb_array_length(pg_temp.rows()->'rows'),1,'one created row');
select is(jsonb_array_length(public.school_grade_history(pg_temp.grade())->'rows'),1,'one initial audit');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),0,'save',pg_temp.value())$$,'P0001','school_grade_changed','different create request cannot overwrite existing row');
select is((public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),1,'save',pg_temp.value(90))->>'revision')::int,2,'correction advances version');
select is((public.school_grade_history(pg_temp.grade())->'rows'->0->'before_value'->>'score')::numeric::int,80,'original score retained');
select is((public.school_grade_history(pg_temp.grade())->'rows'->0->'after_value'->>'score')::numeric::int,90,'corrected score retained');
select is(public.school_grade_history(pg_temp.grade())->'rows'->0->'after_value'->'education_context',public.school_grade_history(pg_temp.grade())->'rows'->0->'before_value'->'education_context','education snapshot unchanged');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),1,'save',pg_temp.value(70))$$,'P0001','school_grade_changed','stale second parent cannot overwrite');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),2,'save',pg_temp.value(101))$$,'P0001','school_grade_invalid','score cannot exceed denominator');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),2,'save',pg_temp.value(80,current_date+1))$$,'P0001','school_grade_invalid','future score rejected');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),2,'save',pg_temp.value(80,current_date-50))$$,'P0001','school_grade_period_change','date cannot silently move evidence to another period');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),2,'save',pg_temp.value()||'{"education_context":null}')$$,'P0001','school_grade_invalid','forged context rejected');
select throws_ok($$update public.grades set score=10 where id=pg_temp.grade()$$,'42501',null,'direct update cannot bypass version check');
select throws_ok($$delete from public.grades where id=pg_temp.grade()$$,'42501',null,'destructive delete unavailable');
select is(jsonb_array_length(public.get_shared_child_view(repeat('a',43))->'grades'),1,'active score visible to authorized teacher share');
select ok(not public.get_shared_child_view(repeat('a',43))::text like '%Private parent note%','private parent note never leaks to teacher share');
select is((public.change_school_grade('50000000-0000-4000-8000-000000008303',pg_temp.grade(),pg_temp.child(),2,'withdraw')->>'revision')::int,3,'withdraw creates revision');
select is(jsonb_array_length(pg_temp.rows()->'rows'),0,'active list hides withdrawn score');
select is(jsonb_array_length(public.list_school_grades(pg_temp.child())->'rows'),0,'older listing also hides withdrawn score');
select is((select count(*)::int from public.grades where id=pg_temp.grade()),0,'direct parent read also hides withdrawn score');
select is(jsonb_array_length(public.get_shared_child_view(repeat('a',43))->'grades'),0,'anonymous teacher projection excludes withdrawn score');
select is(jsonb_array_length(pg_temp.rows(true)->'rows'),1,'withdrawn score remains recoverable');
select is((select revision::int from public.school_grade_sync where child_id=pg_temp.child()),3,'content-free sync signal remains readable after withdrawal');
select is((public.change_school_grade('50000000-0000-4000-8000-000000008303',pg_temp.grade(),pg_temp.child(),2,'withdraw')->>'revision')::int,3,'withdraw replay idempotent');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),3,'save',pg_temp.value())$$,'P0001','school_grade_withdrawn','cannot edit withdrawn record without restoring');
select is((public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),3,'restore')->>'revision')::int,4,'restore creates revision');
select is((pg_temp.rows()->'rows'->0->>'score')::numeric::int,90,'restore retains corrected score');
select is(jsonb_array_length(public.get_shared_child_view(repeat('a',43))->'grades'),1,'restored score returns to authorized share');
select is(jsonb_array_length(public.school_grade_history(pg_temp.grade())->'rows'),4,'create correct withdraw restore all visible');
select is(public.school_grade_history(pg_temp.grade(),3)->'rows'->0->>'action','correct','history cursor loads older changes');
select throws_ok($$select public.school_grade_history(pg_temp.grade(),0)$$,'P0001','invalid_cursor','history cursor validated');
select throws_ok($$select * from gina.school_grade_changes$$,'42501',null,'raw audit not accessible');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),'20000000-0000-4000-8000-000000008302',4,'withdraw')$$,'42501','forbidden','foreign child scope blocked');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008302","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008302","role":"parent"}}',true);
select throws_ok($$select public.school_grade_history(pg_temp.grade())$$,'42501','forbidden','foreign family cannot read score history');
select is((select count(*)::int from public.school_grade_sync),0,'other family cannot watch score activity');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),'20000000-0000-4000-8000-000000008302',4,'withdraw')$$,'42501','forbidden','own child cannot authorize foreign score');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008301","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008301","role":"device","child_id":"20000000-0000-4000-8000-000000008301"}}',true);
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),4,'withdraw')$$,'42501','forbidden','child device cannot alter school score');
select throws_ok($$select public.school_grade_history(pg_temp.grade())$$,'42501','forbidden','child cannot read private parent notes');
select is((select count(*)::int from public.school_grade_sync),0,'child device cannot watch private score activity');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008301","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008301","role":"parent"}}',true);
select lives_ok($$select public.set_child_archived(gen_random_uuid(),pg_temp.child(),0,true)$$,'profile may be archived without losing scores');
select is(jsonb_array_length(public.school_grade_history(pg_temp.grade())->'rows'),4,'archived profile history still readable');
select throws_ok($$select public.change_school_grade(gen_random_uuid(),pg_temp.grade(),pg_temp.child(),4,'withdraw')$$,'P0001','child_archived','archived profile cannot change school scores');
reset role;
select ok(not has_function_privilege('anon','public.change_school_grade(uuid,uuid,uuid,int,text,jsonb)','EXECUTE'),'anonymous write denied');
select ok(not has_function_privilege('authenticated','gina.school_grade_audit()','EXECUTE'),'private audit function denied');
select * from finish();
rollback;
